def get_prime_factorization(n):
    factors = {}
    d = 2
    temp_n = n
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1
    return factors

def get_valuation(n, p):
    if n == 0:
        return float('inf') # Or handle as an error
    if p <= 1:
        return 0
    count = 0
    while n > 0 and n % p == 0:
        count += 1
        n //= p
    return count

def verifier(assign):
    n1, n2, n3, n4 = assign['n1'], assign['n2'], assign['n3'], assign['n4']
    if not all(isinstance(x, int) and x > 0 for x in [n1, n2, n3, n4]):
        return False, None # Must be positive integers

    all_N_prod = n1 * n2 * n3 * n4
    if all_N_prod == 0:
        return False, None # N_i must be positive
    if all_N_prod == 1:
        return True, 1 # Trivial case a=b=c=d=1

    prime_factors = set()
    for n in [n1, n2, n3, n4]:
        factors = get_prime_factorization(n)
        prime_factors.update(factors.keys())

    total_solutions = 1
    for p in prime_factors:
        k = [get_valuation(n, p) for n in [n1, n2, n3, n4]]
        k1, k2, k3, k4 = k[0], k[1], k[2], k[3]

        if max(k1, k3) != max(k2, k4):
            return True, 0

        K = max(k)
        if K == 0:
            sol_p = 1
        else:
            nk = k.count(K)
            if nk < 2:
                sol_p = 0
            elif nk == 4:
                sol_p = 2 * K * K + 4 * K + 1
            elif nk == 3:
                ks = min(k)
                sol_p = 2 * ks + 1
            elif nk == 2:
                # For nk=2, the condition max(k1,k3)=max(k2,k4)=K implies the two K's must be adjacent in the cycle.
                # If they were opposite, e.g. k1=K, k3=K, then max(k1,k3)=K.
                # This would require max(k2,k4)=K, forcing k2 or k4 to be K, which contradicts nk=2.
                others = sorted([val for val in k if val < K])
                ks1, ks2 = others[0], others[1]
                if ks1 == ks2:
                    sol_p = ks1 * ks1 + 3 * ks1 + 1
                else:
                    sol_p = 2 * ks1 + 1
            else: # Should not be reached
                sol_p = 0

        total_solutions *= sol_p

    return True, total_solutions


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

